import java.util.Base64

object BuiltinSources {
    private val chunks = listOf(
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        ""
    )

    fun loadJson(): String {
        val b64 = chunks.joinToString("")
        return String(Base64.getDecoder().decode(b64), Charsets.UTF_8)
    }
}
